  "implementation": "def solve(case):
    import json
    edges = case['edges']
    input_comm = case['communities']
    resolution = case['resolution']

    # build adjacency and degree
    adj = {}
    degree = {}
    for node in input_comm:
        adj[node] = []
        degree[node] = 0
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
        degree[u] += w
        degree[v] += w

    total_weight = sum(degree.values())

    # initialize current communities and community degree totals
    cur_comm = dict(input_comm)
    comm_deg = {}
    for node, comm in cur_comm.items():
        comm_deg[comm] = comm_deg.get(comm, 0) + degree[node]

    moves = []
    changed = True
    while changed:
        changed = False
        nodes_sorted = sorted(cur_comm.keys())
        for node in nodes_sorted:
            cur = cur_comm[node]
            # compute sum of weights from node to each neighbor community
            neigh_comm_weights = {}
            for nb, w in adj[node]:
                nb_comm = cur_comm[nb]
                neigh_comm_weights[nb_comm] = neigh_comm_weights.get(nb_comm, 0) + w

            best_gain = None
            best_comm = cur
            # consider each neighbor community except current
            for cand_comm, w_iC in neigh_comm_weights.items():
                if cand_comm == cur:
                    continue
                w_i_cur = neigh_comm_weights.get(cur, 0)
                gain = (w_iC - resolution * degree[node] * comm_deg[cand_comm] / total_weight) - (w_i_cur - resolution * degree[node] * comm_deg[cur] / total_weight)
                if gain > 0:
                    if best_gain is None or gain > best_gain or (gain == best_gain and cand_comm < best_comm):
                        best_gain = gain
                        best_comm = cand_comm

            if best_comm != cur:
                changed = True
                moves.append({'from': cur, 'node': node, 'to': best_comm})
                # update community assignments and degrees
                cur_comm[node] = best_comm
                comm_deg[cur] -= degree[node]
                comm_deg[best_comm] = comm_deg.get(best_comm, 0) + degree[node]

    # build output communities with same keys as input
    out_comm = {node: cur_comm[node] for node in input_comm}
    return {'communities': out_comm, 'moves': moves}
